import { execFileSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { describe, expect, it } from "vitest";
import { SITE } from "@/lib/constants";

// Regression guard for the wrong install command. `claude install` installs the
// Claude Code native build (see its help text); it never installed this
// plugin, yet the site, README, docs and CLI all told users to paste that
// command with orchestkit/ork as the target. The real flow is marketplace
// add, then plugin install. The patterns below are assembled from parts so
// this file never matches its own scan; keep every comment free of them too.

const REPO = resolve(__dirname, "../../..");

// Built from parts so this file never matches its own scan.
const WRONG_COMMAND = ["claude", "install", "orchestkit"].join(" ");
// The native installer followed by any owner/repo target: a plugin install written as the native
// installer command.
const WRONG_PLUGIN_FORM = ["claude", "install", "[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+"].join(" ");

// Lab pages (docs/<type>--<slug>/ sources and their docs/site/public/lab/
// copies) are owned and regenerated by a separate change. They are dated
// session records, not install instructions a user copies from the site.
const LAB_OWNED = new Set([
	"docs/chore--oss-surface-hygiene/install-matrix.html",
	"docs/feat--cli-published-claim/index.html",
	"docs/site/public/lab/oss-surface-hygiene.html",
]);

function trackedFilesMatching(args: string[]): string[] {
	try {
		const out = execFileSync("git", ["grep", "-l", ...args, "--", "."], {
			cwd: REPO,
			encoding: "utf8",
			maxBuffer: 16 * 1024 * 1024,
		});
		return out.split("\n").filter(Boolean);
	} catch (err) {
		// git grep exits 1 when nothing matches; anything else is a real failure.
		if ((err as { status?: number }).status === 1) return [];
		throw err;
	}
}

type Marketplace = { name: string; plugins: { name: string }[] };

const marketplace = JSON.parse(
	readFileSync(resolve(REPO, ".claude-plugin/marketplace.json"), "utf8"),
) as Marketplace;

describe("plugin install command", () => {
	it("no tracked file tells users to run the native installer for the plugin", () => {
		const offenders = trackedFilesMatching(["-F", "-e", WRONG_COMMAND]).filter(
			(f) => !LAB_OWNED.has(f),
		);
		expect(offenders).toEqual([]);
	});

	it("no tracked file writes a plugin install as the native installer with an owner/repo target", () => {
		const offenders = trackedFilesMatching(["-E", "-e", WRONG_PLUGIN_FORM]).filter(
			(f) => !LAB_OWNED.has(f),
		);
		expect(offenders).toEqual([]);
	});

	it("SITE.installCommand is the marketplace add + plugin install form", () => {
		expect(marketplace.plugins.map((p) => p.name)).toContain("ork");
		expect(
			SITE.installCommand.startsWith(
				"claude plugin marketplace add yonatangross/orchestkit",
			),
		).toBe(true);
		expect(SITE.installCommand).toContain(
			`claude plugin install ork@${marketplace.name}`,
		);
		expect(SITE.installCommand).not.toMatch(/^claude install\b/);
	});

	it("the in-session slash commands match the documented flow", () => {
		expect(SITE.installSlashCommands).toEqual([
			"/plugin marketplace add yonatangross/orchestkit",
			"/plugin install ork",
		]);
	});

	it("the orchestkit npm CLI prints the same command as the site", () => {
		const src = readFileSync(resolve(REPO, "packages/cli/src/cli-core.ts"), "utf8");
		expect(src).toContain(JSON.stringify(SITE.installCommand));
	});
});
